<?php
function help_icon($name) {
    $paths=array('article'=>'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>','question'=>'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3h.01"/>','gift'=>'<path d="M4 10h16v11H4zM3 6h18v4H3zM12 6v15"/><path d="M12 6C5 6 6 0 9 2l3 4c7 0 6-6 3-4z"/>','heart'=>'<path d="M12 21S2 15 2 8a5 5 0 0 1 10-1A5 5 0 0 1 22 8c0 7-10 13-10 13Z"/>','notice'=>'<path d="m3 10 16-6v16L3 14zm4 5 2 6h4l-2-5M22 9v6"/>','download'=>'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>','search'=>'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>');
    return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.(isset($paths[$name])?$paths[$name]:$paths['article']).'</svg>';
}
function help_categories() { return array('使用教程'=>'教程','常见问题'=>'常见问题','活动公告'=>'活动说明','公益节点'=>'公益项目'); }
function help_category_icon($category) { $icons=array('使用教程'=>'article','常见问题'=>'question','活动公告'=>'gift','公益节点'=>'heart');return isset($icons[$category])?$icons[$category]:'article'; }
function help_nav($active) {
    $links='';foreach(help_categories() as $category=>$label){$links.='<a href="/articles?category='.rawurlencode($category).'"'.($active===$category?' class="is-active" aria-current="page"':'').'>'.help_icon(help_category_icon($category)).'<span>'.e($label).'</span></a>';}
    foreach(array('announcements'=>array('/announcements','notice','公告中心'),'downloads'=>array('/downloads','download','软件下载')) as $key=>$item)$links.='<a href="'.$item[0].'"'.($active===$key?' class="is-active" aria-current="page"':'').'>'.help_icon($item[1]).'<span>'.$item[2].'</span></a>';
    return '<aside class="help-reference-sidebar"><h2><a href="/articles">帮助中心</a></h2><nav aria-label="帮助中心">'.$links.'</nav><a class="help-support-link" href="/tickets#new-ticket">需要帮助？提交工单 →</a></aside>';
}
function help_query($name,$max=100) {
    if(!isset($_GET[$name]))return '';
    $value=$_GET[$name];if(!is_string($value)||!mb_check_encoding($value,'UTF-8')||mb_strlen($value,'UTF-8')>$max)throw new InvalidArgumentException('筛选参数无效，请重新选择。');return trim($value);
}
function help_article_list($pdo) {
    try{$q=help_query('q');$category=help_query('category',30);if($category!==''&&!isset(help_categories()[$category]))throw new InvalidArgumentException('文章分类无效。');}catch(InvalidArgumentException $ex){http_response_code(400);return '<div class="help-reference-empty">'.e($ex->getMessage()).'<a href="/articles">返回帮助中心</a></div>';}
    $all=$pdo->query('SELECT * FROM articles WHERE status="published" ORDER BY published_at DESC,id DESC')->fetchAll();$matched=array();$counts=array_fill_keys(array_keys(help_categories()),0);
    foreach($all as $a){if($q!==''&&mb_stripos($a['title'].' '.$a['summary'],$q,0,'UTF-8')===false)continue;$matched[]=$a;if(isset($counts[$a['category']]))$counts[$a['category']]++;}
    $tabs='<a href="/articles'.($q!==''?'?q='.rawurlencode($q):'').'"'.($category===''?' class="is-active" aria-current="page"':'').'>全部 <span>('.count($matched).')</span></a>';
    foreach(help_categories() as $key=>$label)$tabs.='<a href="/articles?'.e(http_build_query(array('category'=>$key,'q'=>$q),'','&',PHP_QUERY_RFC3986)).'"'.($category===$key?' class="is-active" aria-current="page"':'').'>'.e($label).' <span>('.$counts[$key].')</span></a>';
    $cards='';foreach($matched as $a){if($category!==''&&$a['category']!==$category)continue;$cards.='<article class="help-reference-row"><span class="help-reference-tile is-'.e(help_category_icon($a['category'])).'">'.help_icon(help_category_icon($a['category'])).'</span><div class="help-reference-row-copy"><h2><a href="/articles/'.(int)$a['id'].'">'.e($a['title']).'</a></h2><p>'.e($a['summary']).'</p></div><span class="help-reference-badge">'.e($a['category']).'</span><time>'.e(substr((string)$a['published_at'],0,10)).'</time></article>';}
    $art='<div class="help-reference-art" aria-hidden="true"><div class="help-art-orbit"></div><div class="help-art-document"><i>•••</i><b></b><b></b><b></b><b></b></div><span>?</span></div>';
    return '<div class="help-reference-list"><header class="help-reference-hero"><div><h1>帮助中心</h1><p>使用教程、常见问题、活动说明与公益项目，帮助您更好地使用小云铺。</p><form class="help-reference-search" method="get" action="/articles" role="search">'.help_icon('search').'<input type="search" name="q" value="'.e($q).'" maxlength="100" aria-label="搜索文章标题或摘要" aria-describedby="help-search-scope" placeholder="搜索文章，例如：购买流程、VPN、Windows">'.($category!==''?'<input type="hidden" name="category" value="'.e($category).'">':'').'<button class="button" type="submit">搜索</button></form><small id="help-search-scope">搜索已发布文章的标题和摘要，不搜索正文。</small></div>'.$art.'</header><section class="help-reference-list-content"><nav class="help-reference-tabs" aria-label="文章分类">'.$tabs.'</nav><div class="help-reference-rows">'.($cards?:'<div class="help-reference-empty"><h2>暂无匹配文章</h2><p>请尝试其他关键词或分类。</p><a href="/articles">查看全部文章 →</a></div>').'</div><footer class="help-reference-footer"><span>没有找到答案？</span><a href="/tickets#new-ticket">提交工单，由人工协助 →</a><a href="/announcements">查看站点公告 →</a><a href="/downloads">软件下载 →</a></footer></section></div>';
}
function help_article_detail($pdo,$id) {
    $a=false;if(ctype_digit((string)$id)){$s=$pdo->prepare('SELECT * FROM articles WHERE id=? AND status="published"');$s->execute(array($id));$a=$s->fetch();}
    if(!$a){http_response_code(404);return array('文章不存在','<div class="help-reference-empty"><h1>文章不存在或尚未发布</h1><a href="/articles">返回帮助中心 →</a></div>');}
    $body='<nav class="help-reference-breadcrumb" aria-label="面包屑"><a href="/articles">帮助中心</a><span>›</span><a href="/articles?category='.rawurlencode($a['category']).'">'.e($a['category']).'</a><span>›</span><span>'.e($a['title']).'</span></nav><div class="help-reference-layout">'.help_nav($a['category']).'<article class="help-reference-panel help-reference-article"><header><h1>'.e($a['title']).'</h1><div class="help-reference-meta"><span class="help-reference-badge">'.e($a['category']).'</span><time>'.e(substr((string)$a['published_at'],0,10)).'</time></div></header>'.($a['summary']!==''?'<p class="help-reference-summary">'.e($a['summary']).'</p>':'').'<div class="help-reference-prose">'.nl2br(e($a['content'])).'</div><footer class="help-reference-footer"><a href="/articles?category='.rawurlencode($a['category']).'">← 返回分类文章</a><a href="/tickets#new-ticket">仍需帮助？提交工单 →</a></footer></article></div>';
    return array($a['title'],$body);
}
